import{hostRoom,joinRoom}from'./multiplayer.js';
export function openMultiplayer3D({project,room,onHost,onJoin,notify}){const d=document.createElement('dialog');d.className='editor-dialog multiplayer3d';d.innerHTML=`<div class="dialog-top"><h2>Play with friends</h2><button id="close-room3d" aria-label="Close multiplayer">×</button></div>${room?`<p>Room <strong id="room3d-code">${room.session.code}</strong></p><button id="copy-room3d">Copy invite link</button><button id="leave-room3d">Leave room</button>`:`<form id="host3d"><label>Your name<input name="name" maxlength="24" value="Player" required></label><label>Game type<select name="mode"><option value="coop">Play together</option><option value="tag" ${project.gameRules?.mode==='tag'?'selected':''}>Tag · take turns being It</option></select></label><button type="submit" class="primary">Host game</button></form><details><summary>Join using a code</summary><form id="join3d"><label>Room code<input name="code" maxlength="6" required pattern="[A-Za-z0-9]{6}"></label><label>Your name<input name="name" maxlength="24" value="Player" required></label><button type="submit">Join game</button></form></details>`}<p role="status" id="room3d-status"></p>`;document.body.append(d);d.querySelector('#close-room3d').onclick=()=>d.close();d.onclose=()=>d.remove();if(room){d.querySelector('#copy-room3d').onclick=async()=>{try{await navigator.clipboard.writeText(room.link());d.querySelector('#room3d-status').textContent='Invite link copied. Your friend can open it and join.'}catch{d.querySelector('#room3d-status').textContent=room.link()}};d.querySelector('#leave-room3d').onclick=()=>{onHost(null);d.close()}}else{d.querySelector('#host3d').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const values=new FormData(e.target),next={...project,gameRules:{...(project.gameRules||{}),mode:values.get('mode')}};const session=await hostRoom(next,values.get('name'),4);project.gameRules=next.gameRules;onHost(session);d.close();openMultiplayer3D({project,room:{session,link:()=>location.origin+'/play?room='+session.code},onHost,onJoin,notify})}catch(error){d.querySelector('#room3d-status').textContent=error.message}finally{button.disabled=false}};d.querySelector('#join3d').onsubmit=async e=>{e.preventDefault();const values=new FormData(e.target);try{const session=await joinRoom(values.get('code'),values.get('name'));d.close();onJoin(session)}catch(error){d.querySelector('#room3d-status').textContent=error.message}}}d.showModal()}
